  { channel: 'email', customer_name: 'Chris Nguyen', customer_ref: 'C-10038', text: "Small thing but the interest on my bonus saver wasn't paid this month even though I met the conditions. Can you check? Card on file 5555 5555 5555 4444." },
  { channel: 'crm_export', customer_name: 'Zoe Kim', customer_ref: 'C-10039', purpose: 'marketing_personalisation', text: "Customer note: Zoe mentioned she is saving for a wedding next year and might need a personal loan." },
];
return M.map((m, k) => ({
  json: {
    ...m,
    message_id: `DEMO-${String(k + 1).padStart(3, '0')}`,
    received_at: new Date(base + k * 17 * 60e3).toISOString(),
    purpose: m.purpose || 'complaint_triage',
  },
  pairedItem: { item: 0 },
}));

// Normalise every inbound channel into one envelope.
// Works for webhook payloads (body may be one message or {messages:[...]}) and the demo loader.
const out = [];
$input.all().forEach((item, i) => {
  const src = item.json.body ?? item.json;
  const msgs = Array.isArray(src.messages) ? src.messages : [src];
  msgs.forEach((m, j) => {
    const text = String(m.text ?? m.message ?? '').trim();
    out.push({
      json: {
        message_id: m.message_id || `MSG-${Date.now().toString(36)}-${i}${j}${Math.random().toString(36).slice(2, 6)}`,
        channel: m.channel || 'webhook',
        received_at: m.received_at || new Date().toISOString(),
        customer_ref: m.customer_ref || null,
        customer_name: m.customer_name || null,
        purpose: m.purpose || 'complaint_triage',
        text: text.slice(0, 8000),
        truncated: text.length > 8000,
      },
      pairedItem: { item: i },
    });
  });
});
return out.filter(o => o.json.text.length > 0);

