const LIB=(()=>{const luhn=s=>{const d=s.replace(/\D/g,"");if(d.length<13||d.length>19)return false;let sum=0,alt=false;for(let i=d.length-1;i>=0;i--){let n=+d[i];if(alt){n*=2;if(n>9)n-=9}sum+=n;alt=!alt}return sum%10===0};const tfn=s=>{const d=s.replace(/\D/g,"");const w=[1,4,3,7,5,8,6,9,10];return d.length===9&&d.split("").reduce((a,x,i)=>a+ +x*w[i],0)%11===0};const medicare=s=>{const d=s.replace(/\D/g,"");const w=[1,3,7,9,1,3,7,9];if(d.length<10||d.length>11)return false;return d.slice(0,8).split("").reduce((a,x,i)=>a+ +x*w[i],0)%10===+d[8]};const DETECTORS=[{cls:"CARD_NUMBER",re:/\b(?:\d[ -]?){12,18}\d\b/g,ok:luhn},{cls:"MEDICARE",re:/\b[2-6]\d{3}[ ]?\d{5}[ ]?\d(?:[ -]?\d)?\b/g,ok:medicare},{cls:"TFN",re:/\b\d{3}[ -]?\d{3}[ -]?\d{3}\b/g,ok:tfn},{cls:"BSB",re:/\bBSB\s*:?\s*(\d{3}[- ]?\d{3})\b/gi,group:1},{cls:"ACCOUNT_NUMBER",re:/\b(?:account|acct|acc)\s*(?:no\.?|number|#)?\s*:?\s*(\d{6,10})\b/gi,group:1},{cls:"EMAIL",re:/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g},{cls:"PHONE",re:/(?<!\d)(?:\+61[ ]?|0)(?:4\d{2}[ ]?\d{3}[ ]?\d{3}|[2378][ ]?\d{4}[ ]?\d{4})(?!\d)/g},{cls:"DATE_OF_BIRTH",re:/\b(?:DOB|D\.O\.B\.?|date of birth|born on)\s*:?\s*(\d{1,2}[\/.-]\d{1,2}[\/.-]\d{2,4})/gi,group:1},{cls:"ADDRESS",re:/\b\d{1,5}[A-Za-z]?\s+(?:[A-Z][a-z]+\s){1,3}(?:St|Street|Rd|Road|Ave|Avenue|Ct|Court|Pl|Place|Dr|Drive|Cres|Crescent|Way|Lane|Ln|Bvd|Boulevard|Pde|Parade|Tce|Terrace)\b\.?(?:,?\s+[A-Z][a-z]+(?:\s[A-Z][a-z]+)?)?(?:,?\s+(?:VIC|NSW|QLD|SA|WA|TAS|NT|ACT))?(?:\s+\d{4})?/g},{cls:"PERSON_NAME",re:/\b(?:my name is|name\s*:)\s*([A-Z][a-z]+(?:\s[A-Z][a-z'-]+)?)/g,group:1},{cls:"PERSON_NAME",re:/(?:regards|thanks|thank you|cheers|sincerely)[,!.]?[ \t]*\r?\n+[ \t]*([A-Z][a-z]+(?:[ \t][A-Z][a-z'-]+)?)[ \t]*$/gim,group:1}];const SENSITIVE=[{cat:"CRISIS",re:/\b(end (my|it all)|kill myself|suicid\w*|no reason to (live|go on)|take my own life)\b/i},{cat:"FAMILY_VIOLENCE",re:/\b(family violence|domestic violence|abusive (partner|husband|wife|ex)|intervention order|AVO|coercive