      review_required: review.length > 0,
      review_reasons: [...new Set(review)],
      acknowledge_due: isComplaint ? new Date(received.getTime() + P.sla.acknowledge_hours * 3600e3).toISOString() : null,
      resolve_due: isComplaint ? new Date(received.getTime() + resolveDays * 86400e3).toISOString() : null,
      llm_usage: resp?.usage || null,
      ai_finished_at: new Date().toISOString(),
    },
    pairedItem: { item: i },
  });
}
return out;

// ================== BLOCKED: HUMAN ONLY ==================
// AI was not permitted. Build the case for a human, start the clock, fail safe.
return $input.all().map((item, i) => {
  const j = item.json, P = j._policy;
  const received = new Date(j.received_at);
  const days = j.priority === 'URGENT' ? P.sla.resolve_days_urgent : P.sla.resolve_days;
  return {
    json: {
      ...j,
      ai_used: false,
      llm_status: 'not_called',
      output_leak_blocked: false,
      triage: null,
      is_complaint: true, // unknown: treat as complaint so the regulatory clock still runs
      route_to: j.forced_route || 'Human Review Queue',
      review_required: true,
      review_reasons: [...new Set([...j.block_reasons.map(r => `blocked:${r}`), ...j.review_reasons])],
      acknowledge_due: new Date(received.getTime() + P.sla.acknowledge_hours * 3600e3).toISOString(),
      resolve_due: new Date(received.getTime() + days * 86400e3).toISOString(),
      llm_usage: null,
      ai_finished_at: null,
    },
    pairedItem: { item: i },
  };
});

// ================== AUDIT LEDGER ==================
// One immutable row per message: what came in (hash only), what was found,
// what policy did, what the model saw (hash), what it decided, who must review.
// Contains NO raw personal data.
return $input.all().map((item, i) => {
  const j = item.json;
  return {
    json: {
      audit_id: `AUD-${j.message_id}`,
      logged_at: new Date().toISOString(),
      message_id: j.message_id,
      channel: j.channel,
      purpose: j.purpose,
      policy_version: j._policy.version,
      input_sha256: j.input_hash,
      detected_classes: JSON.stringify(j.detected_classes),
      pii_items_found: j.detections.length,
      tokens_issued: j.vault.length,
      items_redacted: j.policy_actions.filter(a => a.startsWith('REDACT')).length,
      sensitive_categories: j.sensitive_context.map(s => s.category).join('|'),
      injection_suspected: j.injection_suspected,
      data_tier: j.data_tier,
      ai_allowed: j.ai_allowed,
      block_reasons: j.block_reasons.join('|'),
      model_id: j.model_id || null,
      prompt_sha256: j.prompt_hash || null,
      llm_status: j.llm_status,
      output_leak_blocked: j.output_leak_blocked,
      category: j.triage?.category || null,
      is_complaint: j.is_complaint,
      product: j.triage?.product || null,
      confidence: typeof j.triage?.confidence === 'number' ? j.triage.confidence : null,
      priority: j.priority,
      route_to: j.route_to,
      review_required: j.review_required,
      review_reasons: j.review_reasons.join('|'),
      input_tokens: j.llm_usage?.input_tokens ?? null,
      output_tokens: j.llm_usage?.output_tokens ?? null,
    },
    pairedItem: { item: i },
  };
});

// ================== CASE QUEUE ==================
// What the operations team works from. Tokenised view only:
// authorised staff resolve tokens via the restricted Token Vault.
return $input.all().map((item, i) => {
  const j = item.json;
  return {
    json: {
      message_id: j.message_id,
      received_at: j.received_at,
      channel: j.channel,
      customer_ref: j.customer_ref || null,
      status: j.review_required ? 'AWAITING_HUMAN_REVIEW' : 'ROUTED',
      priority: j.priority,
      route_to: j.route_to,
      is_complaint: j.is_complaint,
      category: j.triage?.category || 'unclassified',
      product: j.triage?.product || null,
      urgency: j.triage?.urgency || null,
      vulnerability_indicators: (j.triage?.vulnerability_indicators || []).join('; ') || j.sensitive_context.map(s => s.category).join('; '),
      ai_summary: j.triage?.summary || (j.ai_used ? '' : 'AI not permitted: see review reasons'),
      recommended_action: j.triage?.recommended_action || null,
      confidence: typeof j.triage?.confidence === 'number' ? j.triage.confidence : null,
      review_reasons: j.review_reasons.join('; '),
      acknowledge_due: j.acknowledge_due || null,
      resolve_due: j.resolve_due || null,
      tokenised_message: j.safe_text,
      reviewer: null,
      reviewer_decision: null,
    },
    pairedItem: { item: i },
  };
});

// ================== TOKEN VAULT ==================
// The only place raw identifiers live, keyed by message + token.
// Restrict access (separate sheet/DB, least privilege). Redacted classes never land here.
const out = [];
$input.all().forEach((item, i) => {
  const j = item.json;
  for (const v of j.vault) {
    out.push({
      json: {
        message_id: j.message_id,
        token: v.token,
        data_class: v.data_class,
        value: v.value,
        created_at: new Date().toISOString(),
        retention_until: new Date(Date.now() + 7 * 365 * 86400e3).toISOString(),
      },
      pairedItem: { item: i },
    });
  }
});
return out;
